    /// Order 428: concurrent workers must not share agent state. Both CLIs have
    /// documented races on their credential files (OpenCode's auth.json is
    /// unlocked; Codex's is truncate-then-write, upstream #11435/#20213).
    #[test]
    fn forge_worker_state_dirs_are_isolated_per_worker() {
        let w1 = forge_worker_state_env(Some("w1"));
        let w2 = forge_worker_state_env(Some("w2"));
        assert!(!w1.is_empty(), "an instance must produce state overrides");
        for (k, v1) in &w1 {
            let v2 = w2
                .iter()
                .find(|(k2, _)| k2 == k)
                .map(|(_, v)| v)
                .unwrap_or_else(|| panic!("{k} missing for worker 2"));
            assert_ne!(v1, v2, "{k} must differ between workers, else they race");
        }
        let keys: Vec<&str> = w1.iter().map(|(k, _)| k.as_str()).collect();
        assert!(keys.contains(&"XDG_DATA_HOME"));
        assert!(keys.contains(&"XDG_STATE_HOME"));
        assert!(keys.contains(&"CODEX_HOME"));
        assert!(keys.contains(&"TILLANDSIAS_CODEX_STATE_WORKER"));
    }

    #[test]
    fn worker_identity_is_collision_resistant_at_host_and_state_boundary() {
        let spaced = forge_worker_state_env(Some("a b"));
        let dashed = forge_worker_state_env(Some("a-b"));
        let value = |pairs: &[(String, String)], key: &str| -> String {
            pairs
                .iter()
                .find(|(candidate, _)| candidate == key)
                .map(|(_, value)| value.clone())
                .unwrap_or_else(|| panic!("{key} missing"))
        };
        assert_ne!(
            value(&spaced, "CODEX_HOME"),
            value(&dashed, "CODEX_HOME"),
            "host state paths must not collide after readable-name normalization"
        );
        assert_ne!(
            value(&spaced, "TILLANDSIAS_CODEX_STATE_WORKER"),
            value(&dashed, "TILLANDSIAS_CODEX_STATE_WORKER"),
            "the persistence helper needs the exact pre-sanitized identity"
        );
    }

    /// XDG_CONFIG_HOME must NOT be isolated: the forge bakes OpenCode's
    /// permission overlay to /home/forge/.config/opencode/config.json, so
    /// redirecting config per worker would orphan it and silently drop the
    /// lane's permissive defaults.
    #[test]
    fn forge_worker_state_never_redirects_config_home() {
        for inst in [Some("w1"), Some("lead"), Some("worker-9")] {
            let pairs = forge_worker_state_env(inst);
            assert!(
                !pairs.iter().any(|(k, _)| k == "XDG_CONFIG_HOME"),
                "redirecting XDG_CONFIG_HOME orphans the baked OpenCode permission overlay"
            );
        }
    }

    /// Strictly additive: no instance means no overrides at all, so a
    /// single-worker launch is byte-identical to pre-428 behaviour.
    #[test]
    fn absent_forge_instance_emits_no_state_overrides() {
        for raw in [None, Some("")] {
            assert!(
                forge_worker_state_env(raw).is_empty(),
                "instance {raw:?} must emit no state overrides"
            );
        }
        for raw in [Some("   "), Some("---"), Some("///")] {
            assert!(
                !forge_worker_state_env(raw).is_empty(),
                "explicit nonempty instance {raw:?} must not become unscoped"
            );
        }
    }

    /// Order 437: clone-only is the default; the shared host-mount is opt-in
    /// only via TILLANDSIAS_FORGE_HOST_MOUNT=1. Pure over the raw value so it is
    /// testable without env mutation.
    #[test]
    fn forge_host_mount_is_opt_in_only() {
        assert!(
            !forge_host_mount_enabled(None),
            "no env => clone-only default"
        );
        assert!(
            !forge_host_mount_enabled(Some("")),
            "empty => clone-only default"
        );
        assert!(
            !forge_host_mount_enabled(Some("0")),
            "0 => clone-only default"
        );
        assert!(
            !forge_host_mount_enabled(Some("true")),
            "only the literal 1 opts in"
        );
        assert!(
            forge_host_mount_enabled(Some("1")),
            "1 opts into the legacy shared host-mount"
        );
    }

    /// Order 465 residual: the escape hatch must be LOUD. The warning text is
    /// pure, so pin the load-bearing claims: what is reduced, why (rw
    /// host-mount bypassing the isolated clone + mirror-push lane), what still
    /// holds (credential quarantine), and the intended scope (debugging only).
    #[test]
    fn host_mount_isolation_warning_names_reduction_quarantine_and_scope() {
        let warning = forge_host_mount_isolation_warning();
        for needle in [
            "WARNING: WORKSPACE ENCLAVE ISOLATION IS REDUCED",
            "TILLANDSIAS_FORGE_HOST_MOUNT=1",
            "READ-WRITE",
            "bypassing the isolated clone + mirror-push lane",
            "Credentials remain quarantined",
            "DEBUGGING",
        ] {
            assert!(
                warning.contains(needle),
                "escape-hatch warning must state {needle:?}; got:\n{warning}"
            );
        }
        let bordered = warning
            .lines()
            .filter(|line| line.contains("=========="))
            .count();
        assert!(
            bordered >= 2 && warning.lines().count() >= bordered + 3,
            "warning must be an unmissable multi-line bordered block, got:\n{warning}"
        );
        assert!(
            warning
                .lines()
                .all(|line| line.starts_with("[tillandsias]")),
            "every warning line must carry the [tillandsias] stderr prefix"
        );
    }

    /// Order 465 residual pin: BOTH launch-arg builders that honor
    /// TILLANDSIAS_FORGE_HOST_MOUNT=1 must announce the reduced isolation on
    /// the honored branch (Once-gated, so a launch warns exactly once).
    #[test]
    fn host_mount_escape_hatch_branches_emit_the_isolation_guard() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));

        let opencode = source_window(source, "fn build_opencode_forge_args(");
        let optin_idx = opencode
            .find("else if forge_uses_host_mount()")
            .expect("opencode builder keeps the opt-in host-mount branch");
        let warn_idx = opencode
            .find("warn_forge_host_mount_isolation_reduced();")
            .expect("opencode host-mount branch must emit the order-465 guard");
        assert!(
            warn_idx > optin_idx,
            "the guard must fire inside the opt-in branch, not unconditionally"
        );

        let agent = source_window(source, "fn build_forge_agent_run_args_with_vault(");
        assert!(
            agent.contains("warn_forge_host_mount_isolation_reduced();"),
            "agent run-args builder must emit the order-465 guard on its \
             host_mount branch"
        );
    }

    /// Order 427: two workers on one project must not collide. Before the
    /// instance component existed, both got `tillandsias-<project>-forge-<mode>`
    /// and `--replace` made worker 2 destroy worker 1.
    #[test]
    fn forge_container_names_are_instance_scoped_so_workers_coexist() {
        for mode in [
            ForgeAgentMode::Maintenance,
            ForgeAgentMode::OpenCode,
            ForgeAgentMode::Claude,
            ForgeAgentMode::Codex,
            ForgeAgentMode::Antigravity,
        ] {
            let w1 = forge_container_name_for_mode_with_instance("proj", mode, Some("w1"));
            let w2 = forge_container_name_for_mode_with_instance("proj", mode, Some("w2"));
            assert_ne!(
                w1, w2,
                "{mode:?}: distinct workers must get distinct container names, \
                 otherwise --replace makes one destroy the other"
            );
            assert!(
                w1.contains("-w1-"),
                "{mode:?}: readable identity missing from {w1}"
            );
            assert!(
                w2.contains("-w2-"),
                "{mode:?}: readable identity missing from {w2}"
            );
        }
    }

    /// The instance component must be strictly additive: absent or empty
    /// reproduces the pre-427 name exactly, so interactive launches and every
    /// existing fixture are untouched.
    #[test]
    fn absent_or_empty_forge_instance_preserves_legacy_names() {
        for mode in [
            ForgeAgentMode::Maintenance,
            ForgeAgentMode::OpenCode,
            ForgeAgentMode::Claude,
            ForgeAgentMode::Codex,
            ForgeAgentMode::Antigravity,
        ] {
            let legacy = if matches!(mode, ForgeAgentMode::OpenCode) {
                "tillandsias-proj-forge".to_string()
            } else {
                format!("tillandsias-proj-forge-{}", mode.slug())
            };
            for raw in [None, Some("")] {
                assert_eq!(
                    forge_container_name_for_mode_with_instance("proj", mode, raw),
                    legacy,
                    "{mode:?} with instance {raw:?} must reproduce the legacy name"
                );
            }
        }
    }

    /// A worker id reaching a container name must not be able to smuggle
    /// separators, whitespace, or unbounded length past Podman.
    #[test]
    fn forge_instance_identifiers_are_sanitized() {
        let w1 = sanitize_forge_instance("w1");
        assert!(w1.starts_with("w1-"));
        assert_eq!(w1.len(), 35);
        assert_eq!(sanitize_forge_instance(""), "");
        for raw in ["  W1  ", "worker/1", "a b:c", "--lead--", "///", "   "] {
            let sanitized = sanitize_forge_instance(raw);
            assert!(!sanitized.is_empty(), "nonempty {raw:?} became unscoped");
            assert!(sanitized.len() <= 48);
        }
        for (left, right) in [
            ("a b", "a-b"),
            ("Worker", "worker"),
            (
                "0123456789abcdef0123456789abcdef-a",
                "0123456789abcdef0123456789abcdef-b",
            ),
            (
                "forge-tillandsias-codex-20260723T043901Z",
                "forge-tillandsias-codex-20260723T062500Z",
            ),
        ] {
            assert_ne!(
                sanitize_forge_instance(left),
                sanitize_forge_instance(right),
                "distinct raw identities {left:?}/{right:?} collided"
            );
        }
        assert!(
            sanitize_forge_instance(&"x".repeat(200)).len() <= 48,
            "instance ids must be length-capped"
        );
        // A sanitized id must still be a legal Podman name component.
        let s = sanitize_forge_instance("Worker #3 (alpha)");
        assert!(
            s.chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '-'),
            "sanitized id {s} contains characters Podman rejects"
        );
    }

    #[test]
    fn scoped_cleanup_uses_the_same_stable_forge_name_constructor() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let cleanup_window = source_window(source, "async fn cleanup_stack_containers(");
        assert!(
            cleanup_window.contains("let forge_name = forge_container_name(project_name);"),
            "teardown must derive the same instance-scoped name as launch: {cleanup_window}"
        );
        // Order 494 interim guard: the forge is removed through the NON-FORCE
        // variant only — `rm -f` on the forge name is the work-loss vector
        // (it SIGKILLs a running sibling's clone-only workspace).
        // @trace plan/issues/macos-concurrent-lane-launch-kills-sibling-2026-07-27.md
        assert!(
            cleanup_window.contains("remove_container_unless_running(&forge_name)"),
            "forge teardown must go through the order-494 non-force guard: {cleanup_window}"
        );
        assert!(
            !cleanup_window.contains("remove_container(&forge"),
            "the force removal of the forge container must stay dead (order 494): {cleanup_window}"
        );
        assert!(
            !cleanup_window.contains("format!(\"tillandsias-{project_name}-forge\")"),
            "teardown must not fall back to the unscoped legacy name: {cleanup_window}"
        );
    }

