    #[test]
    fn shutdown_poll_backoff_doubles_until_capped() {
        assert_eq!(next_shutdown_poll_delay_ms(25), 50);
        assert_eq!(next_shutdown_poll_delay_ms(50), 100);
        assert_eq!(next_shutdown_poll_delay_ms(125), 250);
        // Order 690-xeda: the cap moved 250ms -> 1s. This loop AWAITS
        // shutdown, so it runs for the life of the process and was the
        // dominant idle wakeup source in the guest -- not the sites the packet
        // named. Updated rather than deleted: the doubling behaviour it pins
        // still matters, only the ceiling changed.
        assert_eq!(next_shutdown_poll_delay_ms(250), 500);
        assert_eq!(next_shutdown_poll_delay_ms(500), SHUTDOWN_POLL_CAP_MS);
        assert_eq!(next_shutdown_poll_delay_ms(u64::MAX), SHUTDOWN_POLL_CAP_MS);
    }

    #[test]
    fn proxy_args_encode_the_expected_container_shape() {
        let args = build_proxy_run_args(&PathBuf::from("/tmp/ca"), "tillandsias-proxy:v1");

        assert!(has_arg(&args, "--detach"));
        assert!(has_arg(&args, "tillandsias-proxy"));
        assert!(has_arg(&args, "proxy"));
        assert!(!has_arg(&args, "--ip"));
        assert!(!has_arg(&args, "10.0.42.2"));
        assert!(has_arg(&args, "DEBUG_PROXY=1"));
        assert!(has_arg(&args, "tillandsias-proxy:v1"));
        // 755-qcxh: the CA private key is delivered as a podman secret owned
        // by the proxy uid; the world-readable key bind mount must never
        // come back.
        assert!(has_arg(&args, "--secret"));
        assert!(has_arg(
            &args,
            "tillandsias-ca-key,uid=1000,gid=1000,mode=0400"
        ));
        assert!(
            !args.iter().any(|a| a.contains("intermediate.key")),
            "CA private key must not be bind-mounted: {args:?}"
        );
    }

    /// 772-shi9 / 795-zshi: the heal must run on the ALREADY-RUNNING path,
    /// which is the commonest path of all.
    ///
    /// `ensure_proxy_running` returns early when the proxy is up, and the
    /// mode clamp inside `ensure_ca_bundle` sits after that return — so a
    /// widened key survived for the VM's lifetime on exactly the path that
    /// happens most. That gap is why the macOS host preambles carry their
    /// own `chmod`, and therefore why they need a shell at all: the host was
    /// compensating for guest housekeeping the guest skipped.
    ///
    /// Asserted by source window rather than by running the function,
    /// because `ensure_proxy_running` needs a live podman. The window is the
    /// function head up to its first `return Ok(())` — i.e. the early-return
    /// block itself.
    #[test]
    fn proxy_already_running_path_still_heals_the_ca_key() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let start = source
            .find("fn ensure_proxy_running(")
            .expect("ensure_proxy_running must exist");
        let tail = &source[start..];
        let end = tail
            .find("return Ok(());")
            .expect("the early-return block must exist");
        let early_return_block = &tail[..end];
        assert!(
            early_return_block.contains("enforce_ca_key_mode("),
            "the proxy-already-running early return must heal the CA key mode \
             before returning, or a widened key survives the VM's lifetime \
             (772-shi9); block was: {early_return_block}"
        );
    }

    // 755-qcxh: a pre-existing world-readable CA key (the old heal target was
    // 0644) must be healed DOWN to owner-only on every ensure pass.
    #[cfg(unix)]
    #[test]
    fn ca_key_mode_heals_world_readable_down_to_0600() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().expect("tempdir");
        let key = dir.path().join("intermediate.key");
        std::fs::write(&key, "not-a-real-key").expect("write");
        std::fs::set_permissions(&key, std::fs::Permissions::from_mode(0o644)).expect("chmod");
        enforce_ca_key_mode(&key).expect("enforce");
        let mode = std::fs::metadata(&key).expect("stat").permissions().mode() & 0o777;
        assert_eq!(mode, 0o600, "CA key must be owner-only after heal");
    }

    /// Order 270: the detach decision, both directions. Unix + not-helper +
    /// no opt-out detaches; the helper itself, a non-unix target, or the
    /// operator opt-out stay in-process.
    #[test]
    fn image_build_detach_decision_both_directions() {
        assert!(image_build_detach_decision(true, false, None));
        assert!(image_build_detach_decision(true, false, Some("1")));
        // helper must never re-detach (one helper, recursion stays inside it)
        assert!(!image_build_detach_decision(true, true, None));
        // setsid is unix-only
        assert!(!image_build_detach_decision(false, false, None));
        // operator opt-out
        assert!(!image_build_detach_decision(true, false, Some("0")));
    }

    /// Order 270: the spawn seam — the detached route hands the helper the
    /// exact ensure coordinates and treats helper exit 0 as success, non-zero
    /// as a failure carrying the log tail. No process is spawned.
    #[test]
    fn detached_image_ensure_routes_through_the_spawn_seam() {
        struct MockDetacher {
            recorded: std::cell::RefCell<Vec<DetachedEnsureRequest>>,
            exit_code: i32,
        }
        impl DetachedImageEnsure for MockDetacher {
            fn run(&self, request: &DetachedEnsureRequest) -> Result<i32, String> {
                self.recorded.borrow_mut().push(DetachedEnsureRequest {
                    root: request.root.clone(),
                    image_name: request.image_name.clone(),
                    image_tag: request.image_tag.clone(),
                    log_path: request.log_path.clone(),
                    debug: request.debug,
                });
                Ok(self.exit_code)
            }
        }

        let ok = MockDetacher {
            recorded: std::cell::RefCell::new(Vec::new()),
            exit_code: 0,
        };
        run_image_ensure_detached(
            Path::new("/some/root"),
            "forge",
            "tillandsias-forge:v1",
            false,
            &ok,
        )
        .expect("helper exit 0 is success");
        let recorded = ok.recorded.borrow();
        assert_eq!(recorded.len(), 1);
        assert_eq!(recorded[0].root, PathBuf::from("/some/root"));
        assert_eq!(recorded[0].image_name, "forge");
        assert_eq!(recorded[0].image_tag, "tillandsias-forge:v1");
        assert!(
            recorded[0]
                .log_path
                .to_string_lossy()
                .contains("image-build-forge.log"),
            "per-image log path: {:?}",
            recorded[0].log_path
        );
        drop(recorded);

        let failing = MockDetacher {
            recorded: std::cell::RefCell::new(Vec::new()),
            exit_code: 7,
        };
        let err = run_image_ensure_detached(
            Path::new("/some/root"),
            "forge",
            "tillandsias-forge:v1",
            false,
            &failing,
        )
        .expect_err("helper non-zero exit is a failure");
        assert!(err.contains("exited 7"), "carries the helper exit: {err}");
    }

    /// Order 270 source-window pins: (a) the detach decision runs BEFORE the
    /// image flock is taken — the parent must never be the lock holder a
    /// retry waits on; (b) the detached path still routes through the SAME
    /// locked identity → decision → build → alias machinery (a retry after
    /// the helper completes therefore observes the cached image and Skips);
    /// (c) main() dispatches the hidden helper mode back into
    /// ensure_image_exists.
    #[test]
    fn detached_image_ensure_preserves_lock_and_decision_machinery() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let window = source_window(source, "pub(crate) fn ensure_image_exists(");
        let detach_idx = window
            .find("image_build_detach_decision(")
            .expect("ensure must consult the detach decision");
        let lock_idx = window
            .find("resource_lock::acquire(")
            .expect("ensure must take the per-image flock");
        assert!(
            detach_idx < lock_idx,
            "detach decision must precede the flock — only the helper locks"
        );
        for anchor in [
            "ensure_image_identity(",
            "ensure_image_decision(",
            "build_image_with_logging(",
            "apply_image_aliases(",
        ] {
            assert!(
                window.contains(anchor),
                "detached ensure must keep the locked decision machinery: {anchor}"
            );
        }
        let main_window = source_window(source, "fn main()");
        let dispatch_idx = main_window
            .find("--internal-ensure-image")
            .expect("main must dispatch the hidden helper mode");
        assert!(
            main_window[dispatch_idx..]
                .find("ensure_image_exists(")
                .is_some(),
            "helper mode must run the same ensure_image_exists body"
        );
    }

    // Regression: smoke-finding/rootless-bridge-network-missing. The dual-home
    // second leg must target the managed `tillandsias-egress` network, never the
    // literal `bridge` (which does not exist on rootless Podman after a reset —
    // the rootless default network is named `podman`).
    #[test]
    fn enclave_egress_dual_home_targets_managed_egress_network() {
        let certs = PathBuf::from("/tmp/ca");
        let proxy = build_proxy_run_args(&certs, "tillandsias-proxy:v1");
        let git = build_git_run_args(
            "alpha",
            None,
            &certs,
            "tillandsias-git:v1",
            None,
            None,
            None,
        );

        // The proxy dual-homes because the spec REQUIRES it (enclave-network
        // spec.md:39) — it is the one sanctioned exception.
        assert!(
            has_arg(&proxy, "tillandsias-enclave,tillandsias-egress"),
            "proxy must dual-home onto the managed egress network: {proxy:?}"
        );

        // Order 606-9wqd. The mirror must NOT. This is the bypass-negative
        // assertion: `tillandsias-egress` is plain NAT with no destination
        // scoping, so an egress leg grants the whole internet to a container
        // whose stated need is one host. Reattaching it must fail here rather
        // than in a security review.
        assert!(
            !has_arg(&git, "tillandsias-enclave,tillandsias-egress"),
            "git mirror must not dual-home onto egress (606-9wqd): {git:?}"
        );
        assert!(
            has_arg(&git, "tillandsias-enclave"),
            "git mirror must still attach to the enclave network: {git:?}"
        );
        assert!(
            git.iter().any(|a| a == "http_proxy=http://proxy:3128"),
            "git mirror must route egress through the proxy once its direct leg \
             is gone, or the push has no path at all: {git:?}"
        );

        for (name, args) in [("proxy", &proxy), ("git", &git)] {
            assert!(
                !has_arg(args, "tillandsias-enclave,bridge"),
                "{name} must not reference the nonexistent `bridge` network: {args:?}"
            );
        }
    }

    // Order 654-7ur4: The provider login helper routes outbound strictly through
