    /// Order 620-duta: the startup preflight must distinguish a kernel that
    /// has `vsock_loopback` from one that does not, and must get the
    /// BUILT-IN case right.
    ///
    /// A module compiled into the kernel never appears in `/proc/modules` but
    /// does get a `/sys/module/<name>` directory. An implementation reading
    /// only `/proc/modules` would report `missing` on a working kernel and
    /// send whoever read it off to modprobe something that cannot be loaded —
    /// worse than printing nothing, because it looks like an answer. That case
    /// is the third assertion below.
    #[test]
    fn vsock_loopback_preflight_classifies_loaded_builtin_and_missing() {
        let loaded_line = "vsock_loopback 16384 0 - Live 0xffffffffc0a12000\n\
                           vmw_vsock_virtio_transport_common 45056 1 vsock_loopback, Live 0x0\n";
        assert_eq!(
            classify_vsock_loopback(false, loaded_line),
            "loaded",
            "a loadable module present in /proc/modules is loaded"
        );

        // Built-in: absent from /proc/modules, present in /sys/module.
        assert_eq!(
            classify_vsock_loopback(true, ""),
            "loaded",
            "a module built into the kernel must not be reported missing"
        );

        // Negative control. Without this the two assertions above would pass
        // for a function that returned "loaded" unconditionally, which is
        // exactly the useless-but-green shape this line exists to avoid.
        assert_eq!(
            classify_vsock_loopback(false, "vmw_vsock_virtio_transport 28672 0 - Live 0x0\n"),
            "missing",
            "neither source reports it: the answer is missing"
        );

        // A different module whose name merely CONTAINS the needle must not
        // count — /proc/modules lines are matched on the first field, not a
        // substring.
        assert_eq!(
            classify_vsock_loopback(false, "vsock_loopback_helper 16384 0 - Live 0x0\n"),
            "missing",
            "a longer module name that starts with the needle is a different module"
        );
    }

    #[test]
    fn github_login_prompts_after_infrastructure_preflight() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let login_window = source_window(
            source,
            "fn run_provider_login(config: &ProviderLoginConfig, debug: bool)",
        );
        let image_idx = login_window
            .find("ensure_image_exists(&root, config.image_name, &image, debug)?")
            .expect("github login must preflight the git image");
        // Infrastructure bring-up is now routed through the container
        // dependency model (order 227) via a single `ensure_git_login` call
        // that topologically satisfies EnclaveNetwork → EgressNetwork →
        // CaBundle → Vault → Proxy.
        let deps_check_idx = login_window
            .find("ensure_git_login(debug)?")
            .expect("github login must satisfy all prerequisite services via the dependency model");
        let infra_health_idx = login_window
            .find("check_auth_required_services(&[\"tillandsias-vault\", \"tillandsias-proxy\"], debug)?")
            .expect("github login must health-check the core services");
        let helper_idx = login_window
            .find("run_command_silent(run, debug)?;")
            .expect("github login must start the helper container before prompts");
        let helper_preflight_idx = login_window
            .find("let required = [\"tillandsias-vault\", container.as_str()]")
            .expect("github login must preflight the actual helper container");
        let helper_health_idx = login_window
            .find("check_auth_required_services(&required, debug)?")
            .expect("github login must run provider-neutral health preflight");
        let prompt_idx = login_window
            .find("prompt_and_store_git_identity()?")
            .expect("github login must prompt for git identity");
        let token_idx = login_window
            .find("config.token_script")
            .expect("github login must prompt for token through the helper");

        for (label, idx) in [
            ("image", image_idx),
            ("deps model", deps_check_idx),
            ("infra health", infra_health_idx),
            ("helper", helper_idx),
            ("helper health", helper_health_idx),
        ] {
            assert!(
                idx < token_idx,
                "{label} preflight must happen before credential prompts: {login_window}"
            );
        }
        assert!(
            deps_check_idx < infra_health_idx,
            "dependency model must complete before the core-service health check: {login_window}"
        );
        assert!(
            infra_health_idx < helper_idx,
            "core service health check must pass before the helper container starts: {login_window}"
        );
        assert!(
            helper_idx < helper_preflight_idx && helper_preflight_idx < helper_health_idx,
            "the health preflight must target the helper container after it starts: {login_window}"
        );
        // Operator directive 2026-07-29: CREDENTIAL FIRST, identity second.
        // Prompting for name/email before the token made operators think
        // those fields were their GitHub credentials.
        assert!(
            token_idx < prompt_idx,
            "token entry must precede the git identity prompt: {login_window}"
        );
    }

    /// The GitHub token prompt must carry the token-creation URL and the
    /// minimum permission set, and the URL must sit alone on its line (no
    /// wrapping punctuation) so terminal renderers linkify it.
    /// @trace spec:gh-auth-script
    #[test]
    fn github_token_prompt_carries_clickable_url_and_minimum_scopes() {
        let script = get_generic_login_token_script(&ProviderId::GitHub);
        assert!(
            script.contains("https://github.com/settings/personal-access-tokens"),
            "GitHub token prompt must name the fine-grained PAT settings page: {script}"
        );
        let url_line = script
            .lines()
            .find(|l| l.contains("https://github.com/settings/personal-access-tokens"))
            .expect("URL line present");
        assert!(
            url_line.contains("  https://github.com/settings/personal-access-tokens\\n"),
            "URL must be alone on its line so terminals can linkify it: {url_line}"
        );
        assert!(
            script.contains("Contents") && script.contains("Read and write"),
            "GitHub token prompt must state the Contents read/write minimum: {script}"
        );
        assert!(
            script.contains("Metadata"),
            "GitHub token prompt must state the Metadata permission: {script}"
        );
        // Other providers keep the bare prompt — no GitHub guidance leaks.
        for other in [
            ProviderId::Claude,
            ProviderId::Codex,
            ProviderId::Antigravity,
        ] {
            let s = get_generic_login_token_script(&other);
            assert!(
                !s.contains("personal-access-tokens"),
                "non-GitHub providers must not carry GitHub token guidance: {s}"
            );
        }
    }

