    /// Order 233 (R5): per-project cleanup must NEVER remove SHARED
    /// containers. `cleanup_stack_containers` removing tillandsias-proxy /
    /// tillandsias-inference tore the shared stack out from under another
    /// project's live forge; only the no-running-forge guard may reach
    /// `remove_shared_stack_containers`.
    #[test]
    fn per_project_cleanup_never_removes_shared_containers() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        // source_window ends at the next `fn ` and would run past the
        // following `async fn remove_shared_stack_containers` (which
        // legitimately names the shared containers); cut the window at that
        // signature explicitly.
        let cleanup_start = source
            .find("async fn cleanup_stack_containers(")
            .expect("cleanup_stack_containers signature present");
        let cleanup_end = source
            .find("async fn remove_shared_stack_containers")
            .expect("remove_shared_stack_containers signature present");
        assert!(
            cleanup_start < cleanup_end,
            "cleanup_stack_containers must precede remove_shared_stack_containers"
        );
        let cleanup = &source[cleanup_start..cleanup_end];
        for shared in [
            "tillandsias-proxy",
            "tillandsias-inference",
            "tillandsias-router",
        ] {
            assert!(
                !cleanup.contains(shared),
                "per-project cleanup_stack_containers must not touch shared container {shared}"
            );
        }
        // The shared remover exists and is reached ONLY via the
        // no-running-forge guard (exactly one call site). Needles are
        // assembled at runtime so this test's own string literals do not
        // count as matches (the test lives inside the file it audits).
        let call_needle = format!("remove_shared_stack_containers({}).await", "client");
        let ref_call_needle = format!("remove_shared_stack_containers({}client).await", "&");
        let call_count =
            source.matches(&call_needle).count() + source.matches(&ref_call_needle).count();
        assert_eq!(
            call_count, 1,
            "remove_shared_stack_containers must be called exactly once (inside the guard)"
        );
        let guard = source_window(source, "async fn cleanup_shared_stack_if_no_running_forge(");
        assert!(
            guard.contains(&call_needle),
            "the guard must be the one shared-remover call site"
        );
        assert!(
            guard.contains("!running_lanes.is_empty()"),
            "the guard must gate on active lane containers before shared removal"
        );
    }

    /// Order 289: the shared-stack liveness predicate must count every
    /// container class that needs the proxy — forge lanes (incl. the
    /// `-forge-maintenance` terminal), provider-login one-shots, and
    /// project browsers — and must ignore stopped ones.
    #[test]
    fn shared_stack_predicate_counts_all_proxy_dependent_lanes() {
        for name in [
            "tillandsias-myproj-forge",
            "tillandsias-myproj-forge-maintenance",
            "tillandsias-myproj-forge-codex",
            "tillandsias-codex-login-12345",
            "tillandsias-browser-myproj",
        ] {
            assert!(
                is_active_lane_container(name, "running"),
                "{name} (running) must keep the shared stack alive"
            );
            // Order 443: a lane mid-launch is alive and must keep the stack up,
            // or an exiting sibling tears it down under a starting forge.
            for starting in ["created", "configured", "initializing", "paused", "up"] {
                assert!(
                    is_active_lane_container(name, starting),
                    "{name} ({starting}) is starting/alive and must keep the shared stack alive"
                );
            }
            // Terminal/dead states must NOT keep the stack alive.
            for terminal in ["exited", "stopped", "dead", "removing", ""] {
                assert!(
                    !is_active_lane_container(name, terminal),
                    "{name} ({terminal:?}) is terminal and must NOT keep the shared stack alive"
                );
            }
        }
        for name in [
            "tillandsias-proxy",
            "tillandsias-inference",
            "tillandsias-router",
            "tillandsias-vault",
            "tillandsias-git-myproj",
        ] {
            assert!(
                !is_active_lane_container(name, "running"),
                "{name} is infrastructure, not a lane — it must not self-perpetuate the stack"
            );
        }
    }

    /// Order 443 slice 3: the shared-stack teardown guard must consult the
    /// launch-in-flight markers (pre-create window) IN ADDITION to the live
    /// lane scan, and both checks must precede the one shared-remover call.
    /// A teardown that skips the marker check tears proxy/git/inference out
    /// from under a sibling launch that has not yet created any container.
    #[test]
    fn shared_stack_teardown_gates_on_foreign_launch_in_flight_markers() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let guard = source_window(source, "async fn cleanup_shared_stack_if_no_running_forge(");
        let lanes_idx = guard
            .find("!running_lanes.is_empty()")
            .expect("guard must keep its active-lane check");
        let marker_idx = guard
            .find("foreign_launches_in_flight(own_launch_marker)")
            .expect("guard must probe foreign launch-in-flight markers");
        let remove_idx = guard
            .find("remove_shared_stack_containers(")
            .expect("guard must still own the shared-remover call");
        assert!(
            lanes_idx < remove_idx && marker_idx < remove_idx,
            "both refcount sources (live lanes + in-flight markers) must be \
             consulted before the shared teardown"
        );
    }

    /// Order 443 slice 3: launch-in-flight markers are pid-scoped, visible
    /// to sibling probes while held, excluded by exact name for the owning
    /// process, and vanish the moment the guard drops (flock-on-death).
    #[test]
    fn shared_stack_launch_marker_lifecycle_and_own_exclusion() {
        const CHILD_ENV: &str = "TILLANDSIAS_LAUNCH_MARKER_LIFECYCLE_CHILD";
        const TEST_NAME: &str = "tests::shared_stack_launch_marker_lifecycle_and_own_exclusion";

        // The full suite concurrently spawns commands. A fork can briefly
        // inherit another test thread's flock fd before O_CLOEXEC takes effect
        // at exec, making an immediate post-drop scan conservatively read
        // "held". Re-exec this one test into its own process so no unrelated
        // suite thread can fork while the marker is live. This keeps the
        // immediate-release assertion meaningful instead of hiding a real
        // leaked guard behind a timing retry (order 584-e8pe).
        if std::env::var(CHILD_ENV).as_deref() != Ok("isolated-child") {
            let lock_runtime = tempfile::tempdir().expect("isolated lock runtime");
            let output = std::process::Command::new(
                std::env::current_exe().expect("resolve current test executable"),
            )
            .env(CHILD_ENV, "isolated-child")
            .env("XDG_RUNTIME_DIR", lock_runtime.path())
            .args(["--exact", TEST_NAME, "--nocapture", "--test-threads=1"])
            .output()
            .expect("re-exec isolated launch-marker lifecycle test");
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            let cleanup = lock_runtime.close();
            assert!(
                output.status.success(),
                "isolated launch-marker lifecycle test failed (status {}):\nstdout:\n{}\nstderr:\n{}",
                output.status,
                stdout,
                stderr
            );
            assert!(
                stdout.contains("1 passed; 0 failed"),
                "isolated child matched no test (libtest exits zero for that); expected one execution:\nstdout:\n{stdout}\nstderr:\n{stderr}"
            );
            cleanup.expect("isolated launch-marker fixture cleanup");
            return;
        }

        let project = format!("marker-test-{}", std::process::id());
        let (marker, guard) =
            acquire_launch_in_flight_marker(&project, false).expect("marker acquires");
        assert!(
            marker.starts_with(LAUNCH_IN_FLIGHT_PREFIX) && marker.contains(&project),
            "marker name must be launch-<project>-<pid>: {marker}"
        );

        // A sibling (own_launch_marker = None) must see the launch in flight…
        let seen_by_sibling = foreign_launches_in_flight(None);
        assert!(
            seen_by_sibling.contains(&marker),
            "sibling probe must see the held marker {marker}, got {seen_by_sibling:?}"
        );
        // …while the owner (passing its own name) must NOT, or the order-298
        // first-launch wipe would never fire.
        let seen_by_owner = foreign_launches_in_flight(Some(&marker));
        assert!(
            !seen_by_owner.contains(&marker),
            "owner must exclude its own marker {marker}, got {seen_by_owner:?}"
        );

        drop(guard);
        assert!(
            !foreign_launches_in_flight(None).contains(&marker),
            "dropped marker must stop blocking teardown"
        );
    }

    /// Order 443 slices 2+3: the launch-path git/inference bring-up must stay
    /// GUARDED — `container_running` decides reuse-vs-create BEFORE each
    /// `run_container_observed` site, so a healthy container in use by a
    /// sibling forge is never re-run (--replace would bounce it).
    #[test]
    fn shared_stack_ensure_guards_git_and_inference_behind_running_checks() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let window = source_window(
            source,
            "async fn ensure_shared_git_and_inference_for_launch(",
        );
        let git_guard_idx = window
            .find("container_running(&git_container_name)")
            .expect("git mirror ensure must check container_running first");
        let git_run_idx = window
            .find("\"forge-launch-git\"")
            .expect("git mirror create site present");
        let inference_guard_idx = window
            .find("container_running(\"tillandsias-inference\")")
            .expect("inference ensure must check container_running first");
        let inference_run_idx = window
            .find("\"forge-launch-inference\"")
            .expect("inference create site present");
        assert!(
            git_guard_idx < git_run_idx,
            "git mirror running-check must precede its run site"
        );
        assert!(
            inference_guard_idx < inference_run_idx,
            "inference running-check must precede its run site"
        );
    }

    /// Order 443 fixture 1 (second-forge ensure leaves shared containers
    /// untouched), driven end to end against the STATEFUL fake podman: with
    /// the git mirror and inference already running, the launch ensure must
    /// issue NO `podman run` for either and their recorded container IDs
    /// must be unchanged — the pre-slice-2 behavior (--replace on every
    /// launch) re-ran both and minted new IDs, bouncing a live sibling.
    ///
    /// Runs only under the fixture env (fake stateful podman on PATH; see
    /// scripts/test-concurrent-forge-shared-stack.sh); a bare `cargo test`
    /// has no podman mock wired and skips loudly, mirroring
    /// source_built_init_and_status_check_smoke_uses_fake_podman.
    #[test]
    fn shared_stack_second_forge_ensure_reuses_running_containers() {
        if std::env::var("LITMUS_PODMAN_MODE").as_deref() != Ok("fake")
            || std::env::var("LITMUS_PODMAN_STATEFUL_CONTAINERS").as_deref() != Ok("1")
        {
            eprintln!(
                "[shared-stack fixture] skipped: needs LITMUS_PODMAN_MODE=fake + \
                 LITMUS_PODMAN_STATEFUL_CONTAINERS=1 (run via scripts/test-concurrent-forge-shared-stack.sh)"
            );
            return;
        }
        let _guard = env_lock();
        let state_dir = std::env::var("LITMUS_PODMAN_STATE_DIR")
            .expect("fixture env must set LITMUS_PODMAN_STATE_DIR");
        let calls_file = std::env::var("LITMUS_PODMAN_CALLS_FILE")
            .expect("fixture env must set LITMUS_PODMAN_CALLS_FILE");

        // Seed through the shared podman layer (idiomatic-launch pin): the
        // sync command resolves the fixture's PATH shim -> stateful mock.
        let podman = |args: &[&str]| {
            let out = podman_cmd_sync()
                .args(args)
                .output_bounded(tillandsias_podman::OperationKind::Container.default_budget())
                .expect("mock podman invokes");
            assert!(out.status.success(), "mock podman {args:?} must succeed");
        };
        let container_id = |name: &str| -> String {
            let path = std::path::Path::new(&state_dir)
                .join("containers")
                .join(name);
            let recorded = std::fs::read_to_string(&path).unwrap_or_else(|e| {
                panic!("tracked container file {} readable: {e}", path.display())
            });
            recorded.lines().nth(1).unwrap_or_default().to_string()
        };

        // Forge A's launch: the stateful mock records the shared containers.
        let git_name = "tillandsias-git-fixtureproj";
        podman(&["run", "--detach", "--name", git_name, "mock-git-image"]);
        podman(&[
            "run",
            "--detach",
            "--name",
            "tillandsias-inference",
            "mock-inference-image",
        ]);
        let git_id_before = container_id(git_name);
        let inference_id_before = container_id("tillandsias-inference");
        assert!(!git_id_before.is_empty() && !inference_id_before.is_empty());

        // Round-trip through the REAL parser: the mock `ps` arm must emit
        // what PodmanClient::list_containers expects.
        let rt = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        let client = PodmanClient::new();
        let listed = rt
            .block_on(client.list_containers("tillandsias-"))
            .expect("list_containers parses the mock ps output");
        let states: std::collections::HashMap<String, String> = listed
            .into_iter()
            .map(|entry| (entry.name, entry.state))
            .collect();
        assert_eq!(states.get(git_name).map(String::as_str), Some("running"));
        assert_eq!(
            states.get("tillandsias-inference").map(String::as_str),
            Some("running")
        );

        // Forge B's launch ensure: everything already running → reuse only.
        std::fs::write(&calls_file, "").expect("truncate calls log");
        rt.block_on(ensure_shared_git_and_inference_for_launch(
            &client,
            "fixtureproj",
            std::path::Path::new("/tmp"),
            "v-fixture",
            Some("https://example.invalid/repo.git"),
            Some("main"),
            true,
        ))
        .expect("second-forge ensure succeeds by reusing the running stack");

        let calls = std::fs::read_to_string(&calls_file).expect("calls log readable");
        assert!(
            !calls
                .lines()
                .any(|l| l.contains(" run ") && l.contains(git_name)),
            "second-forge ensure must NOT re-run the running git mirror:\n{calls}"
        );
        assert!(
            !calls
                .lines()
                .any(|l| l.contains(" run ") && l.contains("tillandsias-inference")),
            "second-forge ensure must NOT re-run the running inference:\n{calls}"
        );
        assert!(
            calls.contains("/srv/git/fixtureproj"),
            "reuse branch must have re-reconciled the mirror (proves the \
             ensure actually ran, not vacuously): \n{calls}"
        );
        assert_eq!(
            container_id(git_name),
            git_id_before,
            "git mirror container ID must be unchanged by a second-forge ensure"
        );
        assert_eq!(
            container_id("tillandsias-inference"),
            inference_id_before,
            "inference container ID must be unchanged by a second-forge ensure"
        );

        // Reproduce the bounce boundary: once inference is genuinely DOWN,
        // the same guard reports not-running — recreation is then correct
        // (the pre-slice-2 bug was re-running it while ALIVE).
        podman(&["stop", "tillandsias-inference"]);
        assert!(
            !crate::vault_bootstrap::container_running("tillandsias-inference"),
            "stopped inference must probe as not running (recreate is then legal)"
        );
    }

    /// Order 666-qbjd: the skew predicate needs POSITIVE old-generation
    /// evidence — a retired shared alias present AND the expected identity
    /// absent. Taxonomy from the packet: pre-659 mirrors skew; post-659 and
    /// post-D13 mirrors are healthy; a degraded inspect (empty aliases, e.g.
    /// the WSL stub) is NOT evidence and keeps today's reuse behavior.
    #[test]
    fn mirror_upgrade_skew_taxonomy() {
        let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<_>>();
        // pre-659: shared aliases only → skew
        assert!(mirror_upgrade_skew(
            &s(&["git-service", "tillandsias-git"]),
            "git-alpha"
        ));
        // post-659 pre-D13: per-project alias → healthy reuse
        assert!(!mirror_upgrade_skew(&s(&["git-alpha"]), "git-alpha"));
        // post-D13: opaque per-mirror alias → healthy reuse
        assert!(!mirror_upgrade_skew(
            &s(&["git-abcdef0123456789"]),
            "git-abcdef0123456789"
        ));
        // transitional dual-identity (retired + expected) → healthy reuse
        assert!(!mirror_upgrade_skew(
            &s(&["git-service", "git-alpha"]),
            "git-alpha"
        ));
        // degraded inspect: no aliases readable → not evidence (WSL stub)
        assert!(!mirror_upgrade_skew(&[], "git-alpha"));
        // unrelated aliases without a retired one → not skew
        assert!(!mirror_upgrade_skew(&s(&["something-else"]), "git-alpha"));
    }

    /// Order 666-qbjd: the skew branch's disposition is keyed on live sibling
    /// lanes — recreate only when none, refuse (with the stable token) when
    /// one exists, and a container-listing failure counts as sibling-live
    /// (leak-not-destroy, the cleanup_shared_stack rule).
    #[test]
    fn mirror_upgrade_skew_branch_recreates_only_without_live_siblings() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let window = source_window(
            source,
            "async fn ensure_shared_git_and_inference_for_launch(",
        );
        let skew_idx = window
            .find("if mirror_upgrade_skew(")
            .expect("ensure must run the upgrade-skew check on the reuse path");
        let skew_window = &window[skew_idx..];
        let empty_idx = skew_window
            .find("siblings.is_empty()")
            .expect("skew disposition must be keyed on live sibling lanes");
        let create_idx = skew_window
            .find("MirrorPlan::Create")
            .expect("skew branch must be able to fall through to the create arm");
        let refuse_idx = skew_window
            .find("mirror upgrade-skew: running mirror")
            .expect("skew branch must refuse with the stable upgrade-skew token");
        assert!(
            empty_idx < create_idx && create_idx < refuse_idx,
            "skew branch shape: sibling check, then recreate, then refuse"
        );
        assert!(
            skew_window[..refuse_idx].contains("container listing failed"),
            "a listing error must count as sibling-live (leak-not-destroy)"
        );
    }

    /// Order 666-qbjd fixture 3b: a running OLD-GENERATION mirror (retired
    /// shared aliases, no per-project identity) with a LIVE sibling lane must
    /// make the launch ensure REFUSE loudly — recreating would destroy the
    /// mirror out from under the sibling (order 443) — and issue no run/rm
    /// for the mirror. Runs only under the fixture env (fake stateful podman
    /// on PATH; see scripts/test-concurrent-forge-shared-stack.sh).
    #[test]
    fn shared_stack_ensure_refuses_upgrade_skewed_mirror_under_live_sibling() {
        if std::env::var("LITMUS_PODMAN_MODE").as_deref() != Ok("fake")
            || std::env::var("LITMUS_PODMAN_STATEFUL_CONTAINERS").as_deref() != Ok("1")
        {
            eprintln!(
                "[shared-stack fixture] skipped: needs LITMUS_PODMAN_MODE=fake + \
                 LITMUS_PODMAN_STATEFUL_CONTAINERS=1 (run via scripts/test-concurrent-forge-shared-stack.sh)"
            );
            return;
        }
        let _guard = env_lock();
        let calls_file = std::env::var("LITMUS_PODMAN_CALLS_FILE")
            .expect("fixture env must set LITMUS_PODMAN_CALLS_FILE");

        let podman = |args: &[&str]| {
            let out = podman_cmd_sync()
                .args(args)
                .output_bounded(tillandsias_podman::OperationKind::Container.default_budget())
                .expect("mock podman invokes");
            assert!(out.status.success(), "mock podman {args:?} must succeed");
        };

        // Seed a pre-659 mirror: shared aliases, legacy name-based hostname.
        let git_name = "tillandsias-git-fixtureproj";
        podman(&[
            "run",
            "--detach",
            "--name",
            git_name,
            "--hostname",
            "git-fixtureproj",
            "--network-alias",
            "git-service",
            "--network-alias",
            "tillandsias-git",
            "mock-git-image",
        ]);
        // ...and a live sibling lane that depends on it.
        podman(&[
            "run",
            "--detach",
            "--name",
            "tillandsias-projB-forge",
            "mock-forge-image",
        ]);

        let rt = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        let client = PodmanClient::new();

        // Round-trip through the REAL parser: the mock's json inspect arm
        // must feed inspect_container the hostname and aliases it recorded.
        let inspected = rt
            .block_on(client.inspect_container(git_name))
            .expect("inspect_container parses the mock json inspect output");
        assert_eq!(inspected.config_hostname, "git-fixtureproj");
        assert_eq!(
            inspected.network_aliases,
            vec!["git-service".to_string(), "tillandsias-git".to_string()]
        );

        std::fs::write(&calls_file, "").expect("truncate calls log");
        let result = rt.block_on(ensure_shared_git_and_inference_for_launch(
            &client,
            "fixtureproj",
            std::path::Path::new("/tmp"),
            "v-fixture",
            Some("https://example.invalid/repo.git"),
            Some("main"),
            true,
        ));
        let err = result.expect_err("skewed mirror + live sibling must refuse the launch");
        assert!(
            err.contains("mirror upgrade-skew"),
            "stable refusal token present: {err}"
        );
        assert!(
            err.contains("tillandsias-projB-forge"),
            "refusal names the live sibling: {err}"
        );
        assert!(
            err.contains("git-fixtureproj"),
            "refusal names the expected per-project identity: {err}"
        );
        let calls = std::fs::read_to_string(&calls_file).expect("calls log readable");
        assert!(
            !calls
                .lines()
                .any(|l| l.contains(" run ") && l.contains(git_name)),
            "no recreate under a live sibling:\n{calls}"
        );
        assert!(
            !calls
                .lines()
                .any(|l| l.contains(" rm ") && l.contains(git_name)),
            "no rm under a live sibling:\n{calls}"
        );
        assert!(
            !calls.contains("/srv/git/fixtureproj"),
            "refusal must fire BEFORE the reuse re-reconcile:\n{calls}"
        );
    }

    /// Order 298: within `ensure_enclave_for_project`, the idempotency wipe
    /// (which removes tillandsias-proxy when no lane is live — always true on
    /// a first launch) must run BEFORE the dependency-model ensure, never
    /// after it. The inverted order shipped in v0.3.260711.8 and handed every
    /// pristine curl-install a forge whose baked proxy env resolved to
    /// nothing ("Could not resolve proxy: proxy").
    #[test]
    fn enclave_bringup_cleans_up_before_ensuring_prerequisites() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));
        let window = source_window(source, "fn ensure_enclave_for_project(");
        let cleanup_idx = window
            .find("cleanup_shared_stack_if_no_running_forge(")
            .expect("ensure_enclave_for_project must run the shared-stack idempotency wipe");
        let ensure_idx = window
            .find("container_deps::ensure_forge_launch(")
            .expect("ensure_enclave_for_project must route through the dependency model");
        assert!(
            cleanup_idx < ensure_idx,
            "shared-stack cleanup must precede ensure_forge_launch — the reverse \
             order tears down the proxy the ensure just started (order 298)"
        );
    }

    /// Drift litmus (order 229): every launch path that creates containers
    /// MUST route through the container dependency model.  A launch that
    /// skips a prerequisite must fail — this is proven at the crate level
    /// by `container_deps::tests::launch_skipping_prerequisite_fails`.
    /// This test verifies the source-code invariant: all CLI-visible launch
    /// entry points reference the dependency model.
    #[test]
    fn all_launch_paths_route_through_dependency_model() {
        let source = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"));

        // All containerized launch paths must route through the dependency
        // model (container_deps module).  Each launch function's body must
        // reference the module directly or delegate to another function that
        // does.  The order-229 known-gap allowlist is eliminated (order 252):
        //   --github-login         via run_provider_login  → ensure_git_login
        //   --list-cloud-projects  via run_list_cloud_projects → ensure_git_login
        //   --<agent> CLI          via run_forge_agent_cli_mode → ensure_enclave_for_project → ensure_forge_launch
        //   tray launch            via ensure_enclave_for_project → ensure_forge_launch
        let dep_model_refs: Vec<&str> = source
            .match_indices("container_deps::")
            .map(|(_, s)| s)
            .collect();
        assert!(
            dep_model_refs.len() >= 6,
            "container_deps must be referenced by at least 6 locations, found {}",
            dep_model_refs.len()
        );

        // Each function that dispatches a containerized launch must route
        // through the dependency model, directly or transitively.
        let launch_fns: [(&str, Option<&[&str]>); 4] = [
            ("fn run_provider_login(", None),
            ("fn run_list_cloud_projects(debug: bool)", None),
            (
                "fn run_forge_agent_cli_mode(",
                Some(&["ensure_enclave_for_project"]),
            ),
            (
                "fn ensure_enclave_for_project(",
                Some(&["container_deps::"]),
            ),
        ];
        for (fn_sig, expected_refs) in &launch_fns {
            let window = source_window(source, fn_sig);
            let directly_routes =
                window.contains("ensure_git_login") || window.contains("container_deps::");
            assert!(
                directly_routes || expected_refs.is_some(),
                "launch path {fn_sig} must route through the container dependency model \
                 (found neither ensure_git_login nor container_deps:: in its body)"
            );
            if let Some(refs) = expected_refs {
                for r in *refs {
                    assert!(
                        window.contains(r),
                        "{fn_sig} must reference {r} in its body"
                    );
                }
            }
        }
    }

    /// Order 387: extend order 314's idempotent-relaunch pattern to the sibling
    /// stack containers. A crashed/exited proxy, git-mirror, or router container
    /// holding the name must not block the next ensure with a Permanent exit-125
    /// — `--replace` atomically removes the exited container.
    #[test]
    fn stack_run_args_use_replace_for_idempotency() {
        let certs = PathBuf::from("/tmp/ca");

        let proxy = build_proxy_run_args(&certs, "tillandsias-proxy:v1");
        assert!(
            has_arg(&proxy, "--replace"),
            "proxy args must include --replace (order 387): {proxy:?}"
        );

        let git = build_git_run_args(
            "alpha",
            None,
            &certs,
            "tillandsias-git:v1",
            None,
            None,
            None,
        );
        assert!(
            has_arg(&git, "--replace"),
            "git-mirror args must include --replace (order 387): {git:?}"
        );

        let router = build_router_run_args(&certs, "tillandsias-router:v1", 8080);
        assert!(
            has_arg(&router, "--replace"),
            "router args must include --replace (order 387): {router:?}"
        );
    }

    // Regression: the egress network must be ensured on every enclave-bootstrap
